import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
const ROOT = process.env.PROBE_ROOT!;
const { AutonomousAgent } = await import(path.join(ROOT, "cli/src/agent.ts"));
const { DEFAULT_CONTINUATION } = await import(path.join(ROOT, "cli/src/types.ts"));
const { startGateway, makeRepo } = await import(path.join(ROOT, "cli/test/helpers/fixtures.ts"));

const quiet = (agent: any) => { agent.ui = new Proxy({}, { get: () => () => {} }); return agent; };
const cfg = (endpoint: string, workspace: string) => ({
  endpoint, model: "m", maxSteps: 40, temperature: 0, workspace, shell: "bash", approvalMode: "auto", fullAccess: true,
  continuation: { ...DEFAULT_CONTINUATION, stagnationSteps: 30, maxRecoveries: 2 },
});
const tools = (calls: any[]) => ({ kind: "tools", calls });
const text = (content: string) => ({ kind: "text", content });
const read = (p: string, s?: number, e?: number) => ({ name: "read_file", args: { path: p, ...(s ? { start_line: s } : {}), ...(e ? { end_line: e } : {}) } });
const sh = (command: string) => ({ name: "run_command", args: { command } });
const lines = (prefix: string, n: number) => Array.from({ length: n }, (_, i) => `${prefix} line ${i + 1}`).join("\n") + "\n";

function log(agent: any) {
  const ran: string[] = [];
  const orig = agent.dispatchToolCall.bind(agent);
  agent.dispatchToolCall = async (call: any, ...rest: any[]) => { ran.push(`${call.function.name} ${typeof call.function.arguments === "string" ? call.function.arguments : JSON.stringify(call.function.arguments)}`); return orig(call, ...rest); };
  return ran;
}
const refusals = (agent: any) => agent.getMessages().filter((m: any) => m.role === "tool" && String(m.content).startsWith("[Nexus refused"));

test("P1 zoom-in pattern: whole file read once, then distinct narrow reads of functions in it (read-only)", { timeout: 120_000 }, async () => {
  const repo = makeRepo({ "src/a.ts": lines("a", 300) });
  const script = [
    tools([read("src/a.ts")]),
    tools([read("src/a.ts", 10, 30)]),
    tools([read("src/a.ts", 50, 70)]),
    tools([read("src/a.ts", 100, 120)]),
    tools([read("src/a.ts", 150, 170)]),
    tools([read("src/a.ts", 200, 220)]),
    tools([read("src/a.ts", 250, 270)]),
    text("done: summary"),
  ];
  const gw = await startGateway((n: number) => script[Math.min(n, script.length) - 1] as any);
  const agent = quiet(new AutonomousAgent(cfg(gw.url, repo) as any));
  const ran = log(agent);
  try {
    const turn = await agent.runTurn("Explain what src/a.ts does.");
    console.log("P1 reason", turn.reason, turn.detail);
    console.log("P1 ran", ran.length, "refused", refusals(agent).length);
    console.log("P1 events", agent.getObjective()?.execution?.recovery?.events.map((e: any) => e.kind).join(","));
  } finally { await gw.close(); fs.rmSync(repo, { recursive: true, force: true }); }
});

test("P2 cat whose output is truncated by the diagnostic-hint append + fold: tail lines later refused?", { timeout: 120_000 }, async () => {
  // b.ts: 40 lines (well under fold's 60-line limit) holding a tsc-style diagnostic so hints get appended.
  const body = Array.from({ length: 40 }, (_, i) => i === 1 ? "src/x.ts(3,5): error TS2322: Type 'number' is not assignable to type 'string'." : `export const value${i} = ${"'" + "x".repeat(60) + "'"}; // line ${i + 1}`).join("\n") + "\n";
  const repo = makeRepo({ "src/b.ts": body, "src/a.ts": lines("a", 50) });
  const script = [
    tools([sh("cat src/b.ts")]),
    tools([read("src/a.ts", 1, 20)]),
    tools([read("src/a.ts", 1, 20)]),
    tools([read("src/a.ts", 1, 20)]),
    tools([read("src/a.ts", 1, 20)]),
    tools([read("src/b.ts", 30, 40)]),
    text("done"),
  ];
  const gw = await startGateway((n: number) => script[Math.min(n, script.length) - 1] as any);
  const agent = quiet(new AutonomousAgent(cfg(gw.url, repo) as any));
  const ran = log(agent);
  try {
    const turn = await agent.runTurn("Look at src/b.ts.");
    const catMsg = agent.getMessages().find((m: any) => m.role === "tool" && /cat src\/b\.ts|value0/.test(String(m.content)));
    console.log("P2 cat message length", String(catMsg?.content).length, "truncated marker:", /\[TRUNCATED\]|lines folded/.test(String(catMsg?.content)), "has line 40:", /line 40/.test(String(catMsg?.content)));
    console.log("P2 reason", turn.reason, turn.detail);
    console.log("P2 ran", JSON.stringify(ran));
    console.log("P2 refused", refusals(agent).map((m: any) => String(m.content).slice(0, 200)));
  } finally { await gw.close(); fs.rmSync(repo, { recursive: true, force: true }); }
});

