test("P3 parallel batch while constrained: new read judged before the stopping refusal, and result order", { timeout: 120_000 }, async () => {
  const repo = makeRepo({ "f.txt": lines("f", 10), "g.txt": lines("g", 10) });
  const script = [
    tools([read("f.txt")]), tools([read("f.txt")]), tools([read("f.txt")]), tools([read("f.txt")]),
    tools([read("g.txt"), read("f.txt"), read("f.txt"), read("f.txt"), read("g.txt", 2, 3)]),
    text("done"),
  ];
  const gw = await startGateway((n: number) => script[Math.min(n, script.length) - 1] as any);
  const agent = quiet(new AutonomousAgent(cfg(gw.url, repo) as any));
  const ran = log(agent);
  try {
    const turn = await agent.runTurn("Look at f.txt and g.txt.");
    console.log("P3 reason", turn.reason, turn.detail);
    console.log("P3 ran", ran.map((r) => r.replace(/ outLen=\d+/, "")).join(" | "));
    const msgs = agent.getMessages();
    const last = msgs.map((m: any, i: number) => [m, i]).filter(([m]: any) => m.role === "assistant" && m.tool_calls?.length === 5).at(-1);
    if (last) {
      const [am, i] = last as any;
      const after = msgs.slice(i + 1, i + 6);
      console.log("P3 order ok", JSON.stringify(after.map((m: any) => m.tool_call_id)) === JSON.stringify(am.tool_calls.map((c: any) => c.id)));
      for (const m of after) console.log("P3 msg", String(m.content).slice(0, 110));
    } else console.log("P3 batch never reached");
  } finally { await gw.close(); fs.rmSync(repo, { recursive: true, force: true }); }
});

