test("P5 constrained: exact repeat of file_info on an ignored, growing log is refused", { timeout: 120_000 }, async () => {
  const repo = makeRepo({ ".gitignore": "build.log\n", "f.txt": lines("f", 10), "build.log": "start\n" });
  const pid = (await import("node:child_process")).spawn("sh", ["-c", "while true; do echo tick >> build.log; sleep 0.3; done"], { cwd: repo, detached: true, stdio: "ignore" });
  const script = [
    tools([{ name: "file_info", args: { path: "build.log" } }]),
    tools([read("f.txt")]), tools([read("f.txt")]), tools([read("f.txt")]), tools([read("f.txt")]),
    tools([{ name: "file_info", args: { path: "build.log" } }]),
    text("done"),
  ];
  const gw = await startGateway((n: number) => script[Math.min(n, script.length) - 1] as any);
  const agent = quiet(new AutonomousAgent(cfg(gw.url, repo) as any));
  const ran = log(agent);
  try {
    const turn = await agent.runTurn("Watch build.log.");
    console.log("P5 reason", turn.reason, turn.detail);
    console.log("P5 ran", ran.map((r) => r.replace(/ outLen=\d+/, "")).join(" | "));
    console.log("P5 refused", refusals(agent).map((m: any) => String(m.content).slice(0, 220)));
    console.log("P5 build.log size now", fs.statSync(path.join(repo, "build.log")).size);
  } finally { try { process.kill(-pid.pid!); } catch {} await gw.close(); fs.rmSync(repo, { recursive: true, force: true }); }
});
EOF
